def _observe_lua_freshness(gs: GameState, bot_version: str,
                           observe_s: float) -> str:
    """Watch `gs` for up to observe_s. Returns one of:
      'fresh'       - saw LUA-VERSION with running == bot_version
      'skew'        - saw LUA-VERSION with running != bot_version (stale)
      'absent'      - sustained lua activity but NO LUA-VERSION (stale lua so
                      old it predates even the heartbeat, e.g. pre-0.3.125)
      'no-activity' - too little lua output to judge (splash/login); caller
                      must NOT remediate on this.
    Early-returns the instant a LUA-VERSION line arrives."""
    seen = {"running": None}
    activity = {"n": 0}

    def _on_ev(ev) -> None:
        if getattr(ev, "kind", None) == "lua_version":
            seen["running"] = (ev.payload or {}).get("running")

    def _on_raw(line: str) -> None:
        if "[LUA-print]" in line:
            activity["n"] += 1

    gs.on_event(_on_ev)
    gs.on_raw_line(_on_raw)
